def page(path,title,description,body,kind=''):
 url='https://dultenrichard.github.io/'+('' if path=='index.html' else path.replace('index.html',''))
 schema={'@context':'https://schema.org','@type':'ProfilePage' if path=='index.html' else 'WebPage','name':title,'url':url,'mainEntity':{'@type':'Person','name':D['name'],'url':'https://dultenrichard.github.io/','sameAs':[x['url'] for x in D['socials']]}}
 if path=='index.html':
  schema['mainEntity'].update({'@id':'https://dultenrichard.github.io/#person','alternateName':['Dulten Richard','Dulten Fromentin'],'image':'https://dultenrichard.github.io/dulten-fromentin-profile.webp','description':D['intro']})
 present=set(re.findall(r'\bid="([^"]+)"',body+HEADER+FOOTER))
 aliases=''.join(f'<span class="anchor-alias" id="{e(a)}" aria-hidden="true"></span>' for a in ALIASES.get(path,[]) if a not in present and a not in ('top','main'))
 display_title='Dulten Richard Fromentin | Leadership & Service' if path=='index.html' else title+' | Dulten Richard Fromentin'
 head=f'''<!doctype html><html lang="en-CA"><head><meta charset="utf-8" /><meta name="viewport" content="width=device-width, initial-scale=1" /><title>{e(display_title)}</title><meta name="description" content="{e(description)}" /><meta name="author" content="Dulten Richard Fromentin" /><meta name="robots" content="index,follow" /><meta name="theme-color" content="#111b22" /><meta name="referrer" content="strict-origin-when-cross-origin" /><link rel="canonical" href="{url}" /><meta property="og:title" content="{e(display_title)}" /><meta property="og:description" content="{e(description)}" /><meta property="og:type" content="website" /><meta property="og:url" content="{url}" /><meta property="og:image" content="https://dultenrichard.github.io/dulten-fromentin-profile.webp" /><meta name="twitter:card" content="summary" /><link href="/dulten-richard-monogram.png" rel="icon" type="image/png" /><link rel="preload" href="/assets/fonts/newsreader-regular.ttf" as="font" type="font/ttf" crossorigin /><link href="/styles.css?v=5" rel="stylesheet" /><script defer src="/data/site-data.js?v=5"></script><script defer src="/site.js?v=5"></script><script type="application/ld+json">{json.dumps(schema,ensure_ascii=False)}</script>'''
 if path=='index.html':head+='<link rel="preload" as="image" href="/assets/images/water-study.webp" />'
 result=head+f'</head><body class="{kind}" id="top">'+HEADER+'<main id="main">'+body+aliases+'</main>'+FOOTER+'</body></html>\n'
 if path=='projects/index.html':
  result=result.replace('name="robots" content="index,follow"','name="robots" content="noindex,follow"').replace('rel="canonical" href="'+url+'"','rel="canonical" href="https://dultenrichard.github.io/"')
 p=ROOT/path;p.parent.mkdir(exist_ok=True,parents=True);p.write_text(result.replace('><','>\n<'))
