body+='</div></div></section>'
body+=f'''<section class="community-section shell" id="community"><div class="hours-display"><strong>{D['communityHours']}</strong><span>completed community-involvement hours</span></div><div class="community-copy"><p class="eyebrow">Community &amp; sport</p><h2>Time outside<br /><em>the classroom.</em></h2><p>Marmora Farmers Market, May–September 2022. Dog walking. Cadet poppy campaigns, parades, Remembrance Day events, and helping older community members.</p><p>I took part in Prince Edward County 4-H’s Maple Syrup and Pizza clubs in 2019, and have participated in Rotary’s Adventure in Citizenship.</p><div class="sport-lines"><div><h3>Rugby</h3><p>Flanker. COSSA silver with my school team in 2025; recognised by PECI Athletics for our May 9 win over THS.</p></div><div><h3>Rowing</h3><p>Brockville Rowing Club alumnus. A 7:53.0 result over 2,000 metres at the 2026 Nancy Storrs Ontario Indoor Rowing Championships.</p></div></div>{link('/sources/#public-records','Public records')}</div></section>'''
