body=f'''{body}<section class="contact-section shell"><div class="contact-direct"><p class="eyebrow">Direct email</p><a class="email-address" href="mailto:{D['email']}">{D['email']}</a><button class="text-button" id="copy-email" type="button" hidden>Copy address</button><p id="copy-status" role="status"></p><p>Brockville, Ontario, Canada</p><div class="contact-socials">'''+''.join(link(x['url'],x['label']) for x in D['socials'])+'''</div><div class="contact-record"><p>Need a certificate or another supporting record?</p>'''+link('/sources/','See the records I keep')+'''</div></div><section class="composer" id="composer" hidden><h2>Write a note.</h2><p>This opens a draft in your email app. Your message isn’t submitted to this website.</p><form id="contact-form"><div class="form-pair"><label>Your name<input id="name" name="name" autocomplete="name" maxlength="100" required /></label><label>Your email<input id="email" name="email" type="email" autocomplete="email" maxlength="200" required /></label></div><label>What is it about?<select name="topic" id="topic"><option value="General">General enquiry</option><option value="Work">Work &amp; opportunities</option><option value="Mentorship">Mentorship &amp; introductions</option><option value="Research">Research</option><option value="Documents">Supporting records</option></select></label><label>Your message<textarea name="message" id="message" rows="5" maxlength="1800" required placeholder="A short introduction and what you have in mind."></textarea></label><button type="submit" class="button-link">Open email draft <span>↗</span></button><p id="form-status" role="status"></p></form></section></section>'''
page('contact/index.html','Contact','Contact Dulten Richard Fromentin about work, research or supporting records.',body,'contact-page')
# Privacy text reflects the actual implementation, including the owner-private review.
body=mast('Privacy','Your choices,<br /><em>clearly stated.</em>','This site uses optional analytics and a local email composer. Updated 10 October 2026.')
body+='''<div class="policy shell"><section id="scope"><h2>What this site does</h2><p>This is my personal website. It presents my experience and provides links to contact me. It has no visitor accounts, advertising profiles, or on-site message database.</p></section><section id="analytics"><h2>Optional analytics</h2><p>Umami Cloud analytics are off until you enable them in this browser. The account uses the EU region. The site honours Global Privacy Control and Do Not Track. Analytics are disabled on the private review domain.</p><p>When enabled on the public site, analytics may measure page views and selected interactions, such as opening navigation, applying a category filter, or downloading a document. Search text, contact messages, names, and email addresses are not sent as event data. URL query strings are excluded.</p><a href="https://docs.umami.is/docs/faq">Umami privacy information ↗</a></section><section id="choices"><h2>Analytics &amp; motion controls</h2><p id="privacy-analytics-status" role="status">Analytics are optional and off by default.</p><div class="privacy-actions"><button id="privacy-enable-analytics" type="button">Enable analytics</button><button id="privacy-disable-analytics" type="button">Disable analytics</button></div><p>These buttons store your choice locally in this browser. The footer’s motion control pauses decorative movement. Reduced-motion preferences from your device are also respected.</p></section><section id="contact-data"><h2>Contact &amp; search</h2><p>The contact composer prepares a mailto draft in your email app. Nothing typed into it is submitted to this website. Search runs locally against this site’s public records. If you send an email, your message is handled by the email services involved.</p></section><section id="hosting"><h2>Hosting</h2><p>The source is maintained on GitHub. This private review is hosted through ChatGPT Sites; the intended public host is GitHub Pages. Hosting providers may process technical request information under their own policies.</p><a href="https://docs.github.com/en/site-policy/privacy-policies/github-general-privacy-statement">GitHub privacy statement ↗</a></section><section id="retention"><h2>Records &amp; enquiries</h2><p>Supporting certificates and private records are shared individually when appropriate. For a question about information held in correspondence, or to request a correction or deletion, contact <a href="mailto:fromentindulten@gmail.com">fromentindulten@gmail.com</a>.</p></section><section id="third-parties"><h2>External links</h2><p>LinkedIn, Instagram, GitHub, and other linked services operate under their own privacy policies. This website does not embed their tracking widgets.</p></section></div>'''
page('privacy/index.html','Privacy','Analytics preferences, motion controls, hosting, contact data and local search.',body,'privacy-page')
page('404.html','Page not found','The requested page could not be found.',mast('404','A different<br /><em>way back.</em>','That address does not lead to a page on this site.',link('/','Return home','button-link')),'not-found')
for href,title in NAV:addsearch(title,'Explore '+title,href,'Page')
addsearch('Experience profile PDF','Download the three-page experience profile','/assets/documents/Dulten-Richard-Fromentin-Experience.pdf','Document')
(ROOT/'data/search-index.json').write_text(json.dumps(SEARCH,ensure_ascii=False,indent=2)+'\n')
(ROOT/'data/site-data.js').write_text('window.SITE_DATA = '+json.dumps({'search':SEARCH,'updated':D['updated'],'email':D['email']},ensure_ascii=False)+';\n')
(ROOT/'editorial.css').write_text('/* Retained for old cached pages. The rebuilt site uses styles.css. */\n')
print('Rebuilt 18 pages from reviewed content; search index:',len(SEARCH),'entries.')
